/* === ANIMATIONS & KEYFRAMES === */

@keyframes pulse-glow-indigo {
  0%,
  100% {
    box-shadow: 0 0 12px rgba(99, 102, 241, 0.3);
  }

  50% {
    box-shadow: 0 0 20px rgba(99, 102, 241, 0.6);
  }
}

@keyframes pulse-glow-blue {
  0%,
  100% {
    box-shadow: 0 0 12px rgba(37, 99, 235, 0.4);
  }

  50% {
    box-shadow: 0 0 20px rgba(37, 99, 235, 0.7);
  }
}

@keyframes pulse-glow-teal {
  0%,
  100% {
    box-shadow: 0 0 12px rgba(20, 184, 166, 0.3);
  }

  50% {
    box-shadow: 0 0 20px rgba(20, 184, 166, 0.6);
  }
}

@keyframes pulse-glow-red {
  0%,
  100% {
    box-shadow: 0 0 12px rgba(239, 68, 68, 0.3);
  }

  50% {
    box-shadow: 0 0 20px rgba(239, 68, 68, 0.6);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes card-pop-in {
  from {
    opacity: 0;
    transform: translateY(15px) scale(0.95);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes move-bg {
  from {
    background-position: 0 0;
  }

  to {
    background-position: 80px 80px;
  }
}

@keyframes progress-bar-stripes {
  from {
    background-position: 2rem 0;
  }

  to {
    background-position: 0 0;
  }
}

@keyframes shake-horizontal {
  0%,
  100% {
    transform: translateX(0);
  }

  10%,
  30%,
  50%,
  70%,
  90% {
    transform: translateX(-5px);
  }

  20%,
  40%,
  60%,
  80% {
    transform: translateX(5px);
  }
}

@keyframes screenFadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes screenFadeOut {
  from {
    opacity: 1;
    transform: translateY(0);
  }

  to {
    opacity: 0;
    transform: translateY(-10px);
  }
}

.fade-in-up {
  animation: fadeIn 0.6s ease-out forwards;
}

/* --- Enhanced Modal Animations --- */

@keyframes backdrop-fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.anim-backdrop-fade-in {
  animation: backdrop-fade-in 0.3s ease-out forwards;
}

@keyframes backdrop-fade-out {
  from {
    opacity: 1;
  }

  to {
    opacity: 0;
  }
}

@keyframes modal-pop-in {
  from {
    opacity: 0;
    transform: scale(0.9);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

.anim-modal-pop-in {
  animation: modal-pop-in 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}

@keyframes modal-pop-out {
  from {
    opacity: 1;
    transform: scale(1);
  }

  to {
    opacity: 0;
    transform: scale(0.95);
  }
}

@keyframes dropdown-in {
  from {
    opacity: 0;
    transform: scale(0.95) translateY(-10px);
  }

  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes dropdown-out {
  from {
    opacity: 1;
    transform: scale(1) translateY(0);
  }

  to {
    opacity: 0;
    transform: scale(0.95) translateY(-10px);
  }
}

@keyframes feedback-slide-in {
  from {
    opacity: 0;
    transform: translateY(15px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse-warning {
  0%,
  100% {
    transform: scale(1);
  }

